import{c as e,Q as o,j as d,m as r}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Session Blindspot Review 二輪 — 規則已經在了，我又違反四次","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-27-session-unknowns-review-2.md","filePath":"research/reports/2026-07-27-session-unknowns-review-2.md","lastUpdated":1785909234000}'),a={name:"research/reports/2026-07-27-session-unknowns-review-2.md"};function s(n,t,c,i,l,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="session-blindspot-review-二輪-—-規則已經在了-我又違反四次" tabindex="-1">Session Blindspot Review 二輪 — 規則已經在了，我又違反四次 <a class="header-anchor" href="#session-blindspot-review-二輪-—-規則已經在了-我又違反四次" aria-label="Permalink to &quot;Session Blindspot Review 二輪 — 規則已經在了，我又違反四次&quot;">​</a></h1><blockquote><p>對象：2026-07-26～27 的 v5 收尾 session（209 個 commit）。 框架：thariqs <code>html-effectiveness/unknowns</code> T1–T11 + Anthropic《The new rules of context engineering for Claude 5 generation models》。 與一輪（<code>2026-07-26-session-unknowns-review.md</code>）的關係：<strong>一輪的結論在本輪被證明不夠</strong>。</p></blockquote><h2 id="_0-一輪的結論、以及它為什麼不夠" tabindex="-1">0. 一輪的結論、以及它為什麼不夠 <a class="header-anchor" href="#_0-一輪的結論、以及它為什麼不夠" aria-label="Permalink to &quot;0. 一輪的結論、以及它為什麼不夠&quot;">​</a></h2><p>一輪找到單一根因：「我採信了一個報告狀態的東西，卻沒有先驗那個東西本身」，並據此把 <code>core.md §TEST</code> 的 oracle 範圍由「先於 loop」擴為「先於採信」，條文明白寫著**「你自己剛寫的 grep」也是 oracle**。</p><p><strong>本輪我又違反四次。</strong> 條文在、範圍對、措辭精確，就是不會開火。</p><table tabindex="0"><thead><tr><th>#</th><th>壞 oracle</th><th>錯在哪</th><th>後果</th></tr></thead><tbody><tr><td>1</td><td><code>grep -E &#39;^[+-][^+-]&#39;</code> 審 diff</td><td><code>+- **項目**</code> 第二字元是 <code>-</code>，被否定字元類排除；同時多抓刪除行</td><td>誤判 sub-agent 少做兩項編輯（實際做了）</td></tr><tr><td>2</td><td>brief 裡的 Done-when 用 Python <code>len(s)</code></td><td>canonical 是 <code>wc -c</code>（bytes），CJK 3 bytes/字</td><td>child 回報數字看似縮水 30%，實為微幅增長</td></tr><tr><td>3</td><td>裸檔名 regex 掃 hook 引用</td><td>撈到外部文章引用、通用範例、截斷字串</td><td>誤報 32 個「死引用」，實際 0</td></tr><tr><td>4</td><td>用<strong>命中數</strong>比較兩個 grep pattern</td><td>兩者都回 3，但是<strong>不同的三條</strong></td><td>差點放行 #1；當場現形</td></tr></tbody></table><p><strong>#4 發生在我正在寫這份 review 的過程中</strong>——我用計數驗證 #1 的修法，計數相同就差點收工。這不是修辭，是同一輪內的實時重現。</p><h2 id="_1-為什麼加規則沒用-本輪最重要的判斷" tabindex="-1">1. 為什麼加規則沒用（本輪最重要的判斷） <a class="header-anchor" href="#_1-為什麼加規則沒用-本輪最重要的判斷" aria-label="Permalink to &quot;1. 為什麼加規則沒用（本輪最重要的判斷）&quot;">​</a></h2><p>Blog 第 1、2 條：移除過度約束的指令，新世代模型判斷力足夠；Anthropic 砍掉 Claude Code system prompt 的 80% 而無性能損失。</p><p>對照本輪：<strong>規則不是不夠精確，是精確到指名了「你剛寫的 grep」仍然無效。</strong> 再寫第五條「記得驗證你的 grep」只會讓常駐層更長、服從率更低。</p><p>一輪的收尾句已經寫過：「缺的是在該檢查的時點會自己開火的東西」。本輪把它推進一步：</p><blockquote><p><strong>臨時驗證指令不會有 hook 幫你開火</strong>（它不是工具呼叫、不是檔案寫入，就是一行 bash）。所以唯一有效的介入是<strong>讓正確做法比錯誤做法更好用</strong>——把易錯的 idiom 換成一支正確的工具，而不是要求自己每次都想起來。</p></blockquote><p>這是 <code>loop.md §L3</code>「結構防線 &gt; prompt 禁令」套用在<strong>自己的驗證習慣</strong>上。</p><h2 id="_2-逐技巧回審" tabindex="-1">2. 逐技巧回審 <a class="header-anchor" href="#_2-逐技巧回審" aria-label="Permalink to &quot;2. 逐技巧回審&quot;">​</a></h2><h3 id="t1-blindspot-pass-—-仍是最大缺席-但缺席位置變了" tabindex="-1">T1 Blindspot Pass — 仍是最大缺席，但缺席位置變了 <a class="header-anchor" href="#t1-blindspot-pass-—-仍是最大缺席-但缺席位置變了" aria-label="Permalink to &quot;T1 Blindspot Pass — 仍是最大缺席，但缺席位置變了&quot;">​</a></h3><p>一輪缺在「改 hook 前沒掃執行路徑」。本輪缺在<strong>更小的尺度</strong>：每次手寫一行驗證 grep 之前，沒有問「這個 pattern 會漏掉哪種輸入」。四次失效全部出在這個尺度。</p><p>尺度小到不值得跑正式 Blindspot Pass——這正是為何處置是工具化而非流程化。</p><h3 id="t7-point-at-a-reference-—-這次錯在「指向了重寫版而非原件」" tabindex="-1">T7 Point at a Reference — 這次錯在「指向了重寫版而非原件」 <a class="header-anchor" href="#t7-point-at-a-reference-—-這次錯在「指向了重寫版而非原件」" aria-label="Permalink to &quot;T7 Point at a Reference — 這次錯在「指向了重寫版而非原件」&quot;">​</a></h3><p>一輪錯在指標會漂移（<code>git show HEAD~1</code>）。本輪錯在 <strong>Done-when 重新實作了一個已有 canonical 命令的量測</strong>。T7 的字面意思是指向 reference，我卻自己抄了一份——抄的那份單位不同。</p><p>已修：<code>task-templates.md</code> 的 <code>Done-when</code> 欄位加註「已有 canonical 命令的量測，逐字照抄，不得改寫或重實作」。</p><h3 id="t9-implementation-notes-—-本輪做對了" tabindex="-1">T9 Implementation Notes — 本輪做對了 <a class="header-anchor" href="#t9-implementation-notes-—-本輪做對了" aria-label="Permalink to &quot;T9 Implementation Notes — 本輪做對了&quot;">​</a></h3><p>四次失效<strong>全部在同一輪內被自己抓到並當場更正</strong>（誤判 sub-agent 後立刻重驗、單位不符後同命令重測、32 個死引用後改問法重掃、計數比較後改比內容）。一輪的三次是「使用者指出後才反轉」。</p><p>差別在於本輪每次宣告前都實際跑了命令看輸出，而不是憑印象斷言。</p><h3 id="t11-quiz-me-before-i-merge-—-機械版持續有效" tabindex="-1">T11 Quiz Me Before I Merge — 機械版持續有效 <a class="header-anchor" href="#t11-quiz-me-before-i-merge-—-機械版持續有效" aria-label="Permalink to &quot;T11 Quiz Me Before I Merge — 機械版持續有效&quot;">​</a></h3><p>每個 commit 前跑 healthcheck / check-references，本輪攔到一次真實漏登（<code>scripts/INDEX.md</code> 未登錄新腳本 → FAIL 1）。這是 gate 真的在工作的證據，不是裝飾。</p><h3 id="t3-four-design-directions-—-本輪主動用了一次" tabindex="-1">T3 Four Design Directions — 本輪主動用了一次 <a class="header-anchor" href="#t3-four-design-directions-—-本輪主動用了一次" aria-label="Permalink to &quot;T3 Four Design Directions — 本輪主動用了一次&quot;">​</a></h3><p>byte 門檻上調時列出兩條路（提高數字 vs 重新定義量測對象），並在記錄中說明使用者選了前者。一輪的失效正是「靜默錨定第一個可行解」。</p><h3 id="t2-t4-t5-t6-t8-t10-—-不適用" tabindex="-1">T2 / T4 / T5 / T6 / T8 / T10 — 不適用 <a class="header-anchor" href="#t2-t4-t5-t6-t8-t10-—-不適用" aria-label="Permalink to &quot;T2 / T4 / T5 / T6 / T8 / T10 — 不適用&quot;">​</a></h3><p>需求由使用者逐輪明確給出，無需求轉譯／原型／方案空間探索／買單文件的施力點。<strong>列出來是為了說明「沒用」是判斷結果而非遺漏。</strong></p><h2 id="_3-本輪落地的處置" tabindex="-1">3. 本輪落地的處置 <a class="header-anchor" href="#_3-本輪落地的處置" aria-label="Permalink to &quot;3. 本輪落地的處置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>修</th><th>防的失效</th><th>型態</th><th>收據</th></tr></thead><tbody><tr><td><code>scripts/diff-added.sh</code></td><td>#1 #4（審 diff 用錯 pattern、用計數當 oracle）</td><td><strong>工具取代 idiom</strong></td><td><code>--self-test</code> 比對內容；並驗舊壞 pattern 產出不同結果（證明測試有區辨力）；真實 diff 上重現 1 vs 3 行的差距</td></tr><tr><td><code>task-templates.md</code> <code>Done-when</code> 欄</td><td>#2（重實作 canonical 量測導致單位漂移）</td><td>條文加註（帶實例）</td><td>—</td></tr><tr><td><code>score-evalpack-v5.sh</code> 的 <code>rejects()</code>/<code>asserted()</code></td><td>合成樣本系統性比真實回應容易</td><td>護欄 + 第三層語料</td><td><code>--qualify</code> 12/12 含真實 rp/rf</td></tr></tbody></table><p><strong>刻意不做的</strong>：不新增「驗證你的 grep」類條文。理由見 §1。</p><h2 id="_4-全域-claude-md-的狀態-查證結果-branch-lag-非-drift" tabindex="-1">4. 全域 CLAUDE.md 的狀態（查證結果：branch lag，非 drift） <a class="header-anchor" href="#_4-全域-claude-md-的狀態-查證結果-branch-lag-非-drift" aria-label="Permalink to &quot;4. 全域 CLAUDE.md 的狀態（查證結果：branch lag，非 drift）&quot;">​</a></h2><p><code>/root/.claude/CLAUDE.md</code> 只有一行 <code>@/tmp/cc-workspace/CLAUDE.md</code>；後者是 <code>main</code> 的淺 clone（<code>9b0c15d</code>）。該版本仍是 v4：auto-load 清單含已刪的 <code>subagent-strategy.md</code>、缺 v5 新增的 <code>loop.md</code>／<code>graph.md</code>、指標指向已封存的 <code>the-loop-harness-v4/</code>。</p><p><strong>但這不是獨立的漂移</strong>——<code>CLAUDE.md</code> 是同一個 git-tracked 檔，本分支已含 v5 版本。<strong>merge 後全域自動同步，無須另修。</strong></p><p>⚠️ <strong>未 merge 前的實際風險</strong>：新開的 session 會拿到 v4 全域路由（指示 auto-load 一個不存在的檔、且少載兩個承載 v5 一半教義的檔）。這不影響本 session（專案層 <code>CLAUDE.md</code> 同時載入且為 v5），但<strong>v5 沒進 main 就等於沒生效</strong>。</p><h2 id="_5-blog-對照-本-workspace-已對齊與未對齊的" tabindex="-1">5. Blog 對照：本 workspace 已對齊與未對齊的 <a class="header-anchor" href="#_5-blog-對照-本-workspace-已對齊與未對齊的" aria-label="Permalink to &quot;5. Blog 對照：本 workspace 已對齊與未對齊的&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Blog 條</th><th>本 workspace 狀態</th></tr></thead><tbody><tr><td>1/2 移除過度約束、讓判斷生效</td><td><strong>已對齊</strong>：<code>output-discipline.md</code> 的硬性禁令已改判斷式；v5 教義總量較 v4 砍半</td></tr><tr><td>4 Progressive disclosure</td><td><strong>已對齊</strong>：三層下沉（閘門→auto-load／細則→refs／流程→skills）為既有紀律</td></tr><tr><td>5 消除重複指令</td><td><strong>本輪修過一次</strong>：<code>CLAUDE.md</code> 五條 auto-load 描述刪除（五檔全載，描述對已載入檔零作用）</td></tr><tr><td>6 自動記憶優於手抄 CLAUDE.md</td><td><strong>已有條文</strong>：<code>core.md §RECORD</code>「平台 auto-memory 免除手抄義務，不免除入庫過門義務」</td></tr><tr><td>7 Rich references 優於散文 spec</td><td><strong>已對齊</strong>：<code>core.md §IDENTIFY</code>「References &gt; 散文 spec」</td></tr><tr><td><code>/doctor</code> 自動 rightsize skills/CLAUDE.md</td><td><strong>未用過</strong>——可作為 skill roster 常駐稅治理的外部對照，列為候選</td></tr></tbody></table><h2 id="_6-給下一輪的一句話" tabindex="-1">6. 給下一輪的一句話 <a class="header-anchor" href="#_6-給下一輪的一句話" aria-label="Permalink to &quot;6. 給下一輪的一句話&quot;">​</a></h2><p>一輪說「規則已經夠了，缺的是會自己開火的東西」。本輪的補充是：<strong>有些失效小到不會有東西幫你開火</strong>——一行臨時 grep 不觸發任何 hook。對這一類，唯一的介入點是把正確做法做成預設路徑，而不是再寫一條要求自己記得的規則。</p>',40)])])}const m=e(a,[["render",s]]);export{g as __pageData,m as default};
